'use strict';
const zlib = require('zlib');
const fs = require('fs');
const path = require('path');

// ==========================================
// .thunder <text>   (aliases: .storm  .lightning)
// "Glowing text in a thunder storm" picture, ePhoto360 style:
// dark teal vortex clouds with a bright eye, a thin jagged lightning bolt
// curling from the top right to the bottom left, and your text as thick
// white marker letters with sketchy scribbles and a cyan glow.
//
//   .thunder Devs
//   .thunder Emmyfrosh AI
//   (or reply to a text message with .thunder)
//
// Everything is drawn by the bot itself (no website, no font, no API).
//
// The storm photo (clouds + lightning) is embedded at the bottom of this file,
// so this is the only file you need. If sharp is missing it falls back to
// drawn clouds + a drawn bolt.
// OPTIONAL: put your own storm_bg.jpg / storm_bg.png next to this file to
// use a different background (use one with no text on it).
// ==========================================

const SIZE = 960;                 // picture is SIZE x SIZE
const MAX_CHARS = 24;             // longest text
const GLOW = [60, 228, 255];      // cyan glow
const CORE = [244, 255, 255];     // white core of letters / bolt
const XS = 0.86;                  // letters a bit narrow, like the reference
const GAP = 0.22;                 // space between letters (x letter size)

// ---------- helpers ----------
function rng(seed) {
  let s = (seed >>> 0) || 1;
  return () => {
    s ^= s << 13; s >>>= 0;
    s ^= s >>> 17;
    s ^= s << 5;  s >>>= 0;
    return s / 4294967296;
  };
}
const clamp = (v, a = 0, b = 1) => (v < a ? a : v > b ? b : v);
const lerp = (a, b, t) => a + (b - a) * t;
const smooth = (a, b, v) => { const t = clamp((v - a) / (b - a)); return t * t * (3 - 2 * t); };

function makeNoise(seed) {
  const rand = rng(seed);
  const perm = new Float32Array(256 * 256);
  for (let i = 0; i < perm.length; i++) perm[i] = rand();
  const at = (x, y) => perm[((y & 255) << 8) | (x & 255)];
  return (x, y) => {
    const xi = Math.floor(x), yi = Math.floor(y);
    const xf = x - xi, yf = y - yi;
    const u = xf * xf * (3 - 2 * xf), v = yf * yf * (3 - 2 * yf);
    return lerp(lerp(at(xi, yi), at(xi + 1, yi), u), lerp(at(xi, yi + 1), at(xi + 1, yi + 1), u), v);
  };
}

// ---------- background: teal storm vortex ----------
const PAL = [
  [0.00, [3, 6, 14]],
  [0.20, [7, 28, 42]],
  [0.46, [19, 80, 94]],
  [0.72, [100, 170, 176]],
  [1.00, [226, 247, 242]],
];
function pal(L) {
  for (let i = 1; i < PAL.length; i++) {
    if (L <= PAL[i][0]) {
      const t = (L - PAL[i - 1][0]) / (PAL[i][0] - PAL[i - 1][0]);
      const a = PAL[i - 1][1], b = PAL[i][1];
      return [lerp(a[0], b[0], t), lerp(a[1], b[1], t), lerp(a[2], b[2], t)];
    }
  }
  return PAL[PAL.length - 1][1];
}

let cloudCache = null;   // drawn once, reused (flipped for variety)
let bgCache;             // undefined = not checked yet, null = no custom bg

async function loadBackground() {
  if (bgCache !== undefined) return bgCache;
  bgCache = null;
  try {
    const sharp = require('sharp');
    const f = ['storm_bg.jpg', 'storm_bg.jpeg', 'storm_bg.png']
      .map((n) => path.join(__dirname, n)).find((p) => fs.existsSync(p));
    const input = f || Buffer.from(BG_B64, 'base64');
    bgCache = await sharp(input).resize(SIZE, SIZE, { fit: 'cover' }).removeAlpha().raw().toBuffer();
  } catch (e) { bgCache = null; }
  return bgCache;
}

function makeClouds() {
  if (cloudCache) return cloudCache;
  const W = SIZE, H = SIZE;
  const noise = makeNoise(20241004), warp = makeNoise(5150);
  const cx = W * 0.5, cy = H * 0.5;
  const F = new Float32Array(W * H);

  // 1) cloud height field: swirling, domain-warped fractal noise
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const dx = (x - cx) / W, dy = (y - cy) / W;
      const r = Math.sqrt(dx * dx + dy * dy);
      const a = 0.7 * Math.pow(1 - Math.min(r / 0.5, 1), 1.5);   // gentle vortex twist
      const ca = Math.cos(a), sa = Math.sin(a);
      let px = dx * ca - dy * sa, py = dx * sa + dy * ca;
      const wx = warp(px * 3 + 11, py * 3 + 5) - 0.5, wy = warp(px * 3 + 57, py * 3 + 23) - 0.5;
      px += wx * 0.1; py += wy * 0.1;
      const zoom = 1;     // finer clouds far away (centre)
      let n = 0, amp = 0.5, f = 2.2 * zoom, tot = 0;
      for (let o = 0; o < 6; o++) {
        n += amp * (1 - Math.abs(2 * noise(px * f + 40 + o * 7.3, py * f + 40 - o * 3.1) - 1));
        tot += amp; amp *= 0.46; f *= 2.1;
      }
      F[y * W + x] = n / tot + 0.12 * Math.sin(r * 26 + n * 2.5);
    }
  }

  // 2) lighting: the bright eye lights the cloud lumps that face it
  const rgb = new Uint8ClampedArray(W * H * 3);
  const gcx = W * 0.5, gcy = H * 0.52;
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const i = y * W + x;
      const dx = (x - gcx) / W, dy = (y - gcy) / W;
      const r = Math.sqrt(dx * dx + dy * dy) || 1e-6;
      const sx = clamp(Math.round(x - (dx / r) * 6), 0, W - 1);
      const sy = clamp(Math.round(y - (dy / r) * 6), 0, H - 1);
      const shade = clamp((F[i] - F[sy * W + sx]) * 11, -0.3, 0.55);
      const d = clamp((F[i] - 0.38) / 0.5);
      const fade = 1 - 0.62 * smooth(0.12, 0.6, r);
      const glow = Math.exp(-Math.pow(r / 0.17, 2));
      let L = (0.06 + 0.5 * Math.pow(d, 1.2) + shade * 0.75) * fade
            + 0.78 * glow * (0.55 + 0.45 * (1 - d * 0.8));
      L *= 1 - 0.8 * smooth(0.36, 0.8, r);                      // dark vignette
      L = clamp(L);
      const c = pal(L);
      const edge = smooth(0.45, 0.85, r) * 0.55;               // dark purple-navy corners
      rgb[i * 3] = lerp(c[0], 14, edge);
      rgb[i * 3 + 1] = lerp(c[1], 8, edge);
      rgb[i * 3 + 2] = lerp(c[2], 26, edge);
    }
  }
  cloudCache = rgb;
  return rgb;
}

