// D, E, V, S are the real hand-drawn letters cut from the reference picture
// (data at the bottom of this file). Every other letter is drawn by code.
let realCache = null;
function glyphOf(ch) {
  ch = ch.toUpperCase();
  if (!realCache) {
    realCache = {};
    for (const c of Object.keys(REAL_GLYPHS)) {
      const r = REAL_GLYPHS[c];
      realCache[c] = {
        w: ((r.nx1 - r.nx0 + 1) / REAL_CAP * 1.4) / XS, l: [],
        real: Object.assign({ pixels: zlib.inflateSync(Buffer.from(r.data, 'base64')) }, r),
      };
    }
  }
  return realCache[ch] || GLYPHS[ch] || GLYPHS[' '];
}

// paste a real letter (bitmap) into a mask, scaled to the letter size k
function blitReal(mask, R, x, top, k) {
  const s = (1.4 * k) / REAL_CAP;
  const dx0 = x + (R.bx - R.nx0) * s, dy0 = top + (R.by - REAL_TOP) * s;
  const X0 = Math.max(0, Math.floor(dx0)), X1 = Math.min(SIZE - 1, Math.ceil(dx0 + R.w * s));
  const Y0 = Math.max(0, Math.floor(dy0)), Y1 = Math.min(SIZE - 1, Math.ceil(dy0 + R.h * s));
  const px = R.pixels;
  const at = (u, v) => (u < 0 || v < 0 || u >= R.w || v >= R.h ? 0 : px[v * R.w + u]);
  for (let Y = Y0; Y <= Y1; Y++) {
    for (let X = X0; X <= X1; X++) {
      const u = (X - dx0) / s - 0.5, v = (Y - dy0) / s - 0.5;
      const ui = Math.floor(u), vi = Math.floor(v), fu = u - ui, fv = v - vi;
      const val = (lerp(lerp(at(ui, vi), at(ui + 1, vi), fu), lerp(at(ui, vi + 1), at(ui + 1, vi + 1), fu), fv)) / 255;
      const i = Y * SIZE + X;
      if (val > mask[i]) mask[i] = val;
    }
  }
}

// small caps: a lowercase letter is drawn as a smaller capital (CAPITALS stay full size)
const SMALL = 0.76;
const scOf = (ch) => (ch >= 'a' && ch <= 'z' ? SMALL : 1);

// text -> up to 2 lines (long text is split at the space nearest the middle)
function layoutLines(raw) {
  let t = String(raw || '').replace(/[^A-Za-z0-9.,!?&'\- ]/g, '').replace(/\s+/g, ' ').trim().slice(0, MAX_CHARS);
  if (!t) return [];
  if (t.length <= 10 || !t.includes(' ')) return [t];
  const mid = t.length / 2;
  let best = -1;
  for (let i = 0; i < t.length; i++) if (t[i] === ' ' && (best < 0 || Math.abs(i - mid) < Math.abs(best - mid))) best = i;
  return [t.slice(0, best).trim(), t.slice(best + 1).trim()];
}

// ---------- drawing on a single-channel mask ----------
function newMask() { return new Float32Array(SIZE * SIZE); }

function strokeLine(mask, x0, y0, x1, y1, width, strength = 1) {
  const pad = width / 2 + 1.5;
  const minX = Math.max(0, Math.floor(Math.min(x0, x1) - pad)), maxX = Math.min(SIZE - 1, Math.ceil(Math.max(x0, x1) + pad));
  const minY = Math.max(0, Math.floor(Math.min(y0, y1) - pad)), maxY = Math.min(SIZE - 1, Math.ceil(Math.max(y0, y1) + pad));
  const vx = x1 - x0, vy = y1 - y0, len2 = vx * vx + vy * vy || 1e-6;
  for (let y = minY; y <= maxY; y++) {
    for (let x = minX; x <= maxX; x++) {
      let t = ((x - x0) * vx + (y - y0) * vy) / len2;
      t = t < 0 ? 0 : t > 1 ? 1 : t;
      const dx = x - (x0 + t * vx), dy = y - (y0 + t * vy);
      const cov = clamp(width / 2 + 0.5 - Math.sqrt(dx * dx + dy * dy)) * strength;
      const i = y * SIZE + x;
      if (cov > mask[i]) mask[i] = cov;
    }
  }
}

function strokePath(mask, pts, width, strength) {
  for (let i = 0; i < pts.length - 1; i++) strokeLine(mask, pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1], width, strength);
}

// width + brightness change along the path (t = 0..1): thin & dim at the ends
function strokeTapered(mask, pts, wFn, sFn) {
  const n = pts.length - 1;
  for (let i = 0; i < n; i++) {
    const t = (i + 0.5) / n;
    strokeLine(mask, pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1], wFn(t), sFn(t));
  }
}

// fast blur (3 box blurs = nearly a gaussian)
function boxBlur(src, radius) {
  const r = Math.max(1, Math.round(radius));
  const tmp = new Float32Array(src.length), out = new Float32Array(src.length);
  const run = (from, to, horizontal) => {
    for (let a = 0; a < SIZE; a++) {
      let sum = 0;
      const idx = (k) => (horizontal ? a * SIZE + k : k * SIZE + a);
      for (let k = -r; k <= r; k++) sum += from[idx(Math.min(SIZE - 1, Math.max(0, k)))];
      for (let k = 0; k < SIZE; k++) {
        to[idx(k)] = sum / (2 * r + 1);
        sum += from[idx(Math.min(SIZE - 1, k + r + 1))] - from[idx(Math.max(0, k - r))];
      }
    }
  };
  let a = src;
  for (let pass = 0; pass < 3; pass++) {
    run(a, tmp, true);
    run(tmp, out, false);
    a = out;
  }
  return out;
}

// the letters: thick marker strokes + thin sketchy scribbles that overshoot
function drawText(lines, rand) {
  const core = newMask();      // thick marker
  const scribble = newMask();  // thin sketchy lines
  const n = lines.length;

  const widthOf = (str, k) => [...str].reduce((s, ch) => s + glyphOf(ch).w * XS * k * scOf(ch), 0) + (str.length - 1) * GAP * k;
  let k = SIZE * (n === 1 ? 0.078 : 0.068);
  const longest = Math.max(...lines.map((l) => widthOf(l, 1)));
  k = Math.min(k, (SIZE * 0.66) / longest);
  if (n === 1) k = Math.max(k, Math.min((SIZE * 0.30) / longest, SIZE * 0.1));   // short words: bigger

  const capH = 1.4 * k, gapY = 0.45 * k;
  const blockH = n * capH + (n - 1) * gapY;
  const midY = SIZE * 0.47;
  let top = midY - blockH / 2;
  const jit = (pts, a) => pts.map(([px, py]) => [px + (rand() - 0.5) * 2 * a, py + (rand() - 0.5) * 2 * a]);

  // round the corners a little (hand-drawn look)
  const chaikin = (pts) => {
    const o = [pts[0]];
    for (let i = 0; i < pts.length - 1; i++) {
      const p = pts[i], q = pts[i + 1];
      o.push([0.75 * p[0] + 0.25 * q[0], 0.75 * p[1] + 0.25 * q[1]], [0.25 * p[0] + 0.75 * q[0], 0.25 * p[1] + 0.75 * q[1]]);
    }
    o.push(pts[pts.length - 1]);
    return o;
  };

  for (const str of lines) {
    let x = SIZE / 2 - widthOf(str, k) / 2;
    for (const ch of str) {
      const g = glyphOf(ch);
      const kk = k * scOf(ch);                 // letter size (small for lowercase)
      const topc = top + (1.4 * k - 1.4 * kk);  // same baseline for big and small letters
      // every letter is a bit tilted / shifted, like it was written by hand
      const rot = (rand() - 0.5) * 0.1, dyL = (rand() - 0.5) * 0.06 * kk;
      const lcx = x + (g.w * XS * kk) / 2, lcy = topc + 0.7 * kk;
      const tr = ([px, py]) => {
        const X = x + px * XS * kk - lcx, Y = topc + py * kk + dyL - lcy;
        return [lcx + X * Math.cos(rot) - Y * Math.sin(rot), lcy + X * Math.sin(rot) + Y * Math.cos(rot)];
      };
      if (g.real) blitReal(core, g.real, x, topc, kk);
      for (const line of g.l) {
        const pts = chaikin(line).map(tr);
        strokePath(core, jit(pts, 0.025 * kk), 0.155 * kk, 1);      // main marker stroke
        strokePath(core, jit(pts, 0.05 * kk), 0.1 * kk, 0.95);   // 2nd pass = uneven thickness
        const copies = 6 + Math.floor(rand() * 4);
        for (let c = 0; c < copies; c++) {
          const jp = jit(pts, 0.05 * kk);
          const over = (p, q) => {
            const dx = p[0] - q[0], dy = p[1] - q[1], d = Math.hypot(dx, dy) || 1;
            const ext = (0.02 + rand() * 0.12) * kk;
            return [p[0] + (dx / d) * ext, p[1] + (dy / d) * ext];
          };
          jp[0] = over(jp[0], jp[1]);
          jp[jp.length - 1] = over(jp[jp.length - 1], jp[jp.length - 2]);
          strokePath(scribble, jp, 1.4 + rand() * 1.4, 0.95);
        }
      }
      // thin looping scribbles across the letter
      if (g.l.length) {
        const loops = rand() < 0.5 ? 1 : 0;
        for (let q = 0; q < loops; q++) {
          const lx = x + (0.2 + rand() * 0.6) * g.w * XS * kk, ly = topc + (0.3 + rand() * 0.8) * kk;
          const rx = (0.2 + rand() * 0.25) * kk, ry = (0.25 + rand() * 0.3) * kk;
          const a0 = rand() * 6.28, sweep = 3.5 + rand() * 4, lp = [];
          for (let i = 0; i <= 24; i++) {
            const a = a0 + (sweep * i) / 24, rr = 1 + 0.15 * Math.sin(a * 3 + rand() * 0.3);
            lp.push([lx + Math.cos(a) * rx * rr, ly + Math.sin(a) * ry * rr]);
          }
          strokePath(scribble, lp, 0.9 + rand() * 0.6, 0.75);
        }
      }
      x += g.w * XS * kk + GAP * k;
    }
    top += capH + gapY;
  }

  // a few long stray scribble lines around the text
  const spread = Math.max(...lines.map((l) => widthOf(l, k))) / 2;
  for (let i = 0; i < 6; i++) {
    const ax = SIZE / 2 + (rand() - 0.5) * 2 * spread * 1.05, ay = midY + (rand() - 0.5) * blockH * 1.15;
    const ang = (rand() < 0.5 ? -1 : 1) * (0.25 + rand() * 0.9), len = (0.35 + rand() * 0.8) * k;
    strokeLine(scribble, ax, ay, ax + Math.cos(ang) * len, ay + Math.sin(ang) * len, 1.3, 0.85);
  }
  return { core, scribble, k };
}

// lightning bolt: thin jagged curve from the top right, down, then sweeping
// under the text to the bottom left. Dim at both ends, brightest in the middle.
function makeBolt(rand, flip) {
  const ctrl = [
    [0.790, 0.328], [0.776, 0.417], [0.760, 0.500], [0.745, 0.563], [0.720, 0.604],
    [0.667, 0.630], [0.615, 0.646], [0.563, 0.651], [0.500, 0.667], [0.460, 0.720],
    [0.430, 0.730], [0.365, 0.766], [0.310, 0.770], [0.260, 0.766], [0.200, 0.730],
  ].map(([x, y]) => [SIZE * (x + (rand() - 0.5) * 0.02), SIZE * (y + (rand() - 0.5) * 0.016)]);

  const cr = (p0, p1, p2, p3, t) => {
    const t2 = t * t, t3 = t2 * t;
    return [0, 1].map((i) => 0.5 * ((2 * p1[i]) + (-p0[i] + p2[i]) * t + (2 * p0[i] - 5 * p1[i] + 4 * p2[i] - p3[i]) * t2 + (-p0[i] + 3 * p1[i] - 3 * p2[i] + p3[i]) * t3));
  };
  const dense = [];
  for (let i = 0; i < ctrl.length - 1; i++) {
    const p0 = ctrl[Math.max(0, i - 1)], p1 = ctrl[i], p2 = ctrl[i + 1], p3 = ctrl[Math.min(ctrl.length - 1, i + 2)];
    for (let s = 0; s < 6; s++) dense.push(cr(p0, p1, p2, p3, s / 6));
  }
  dense.push(ctrl[ctrl.length - 1]);

  const jag = (p, q, disp, depth) => {
    if (depth === 0) return [p, q];
    const len = Math.hypot(q[0] - p[0], q[1] - p[1]) || 1;
    const nx = -(q[1] - p[1]) / len, ny = (q[0] - p[0]) / len;
    const off = (rand() - 0.5) * 2 * disp;
    const m = [(p[0] + q[0]) / 2 + nx * off, (p[1] + q[1]) / 2 + ny * off];
    return [...jag(p, m, disp * 0.6, depth - 1).slice(0, -1), ...jag(m, q, disp * 0.6, depth - 1)];
  };
  let main = [];
  for (let i = 0; i < dense.length - 1; i++) {
    const seg = jag(dense[i], dense[i + 1], SIZE * 0.0032, 2);
    main = main.concat(i ? seg.slice(1) : seg);
  }
  const branches = [];
  for (let i = 0; i < 2; i++) {
    const s0 = main[Math.floor(main.length * (0.2 + rand() * 0.6))];
    const e = [s0[0] + (rand() - 0.5) * SIZE * 0.07, s0[1] + 0.015 * SIZE + rand() * SIZE * 0.04];
    branches.push(jag(s0, e, SIZE * 0.012, 3));
  }
  const mirror = (pts) => (flip ? pts.map(([x, y]) => [SIZE - x, y]) : pts);
  return { main: mirror(main), branches: branches.map(mirror) };
}

// ---------- put everything together ----------
async function render(text, seed) {
  const rand = rng(seed);
  const lines = layoutLines(text);
  if (!lines.length) throw new Error('empty text');

  const flipRand = rand() < 0.5;
  const bg = await loadBackground();
  const flip = bg ? false : flipRand;   // the photo has its own bolt, keep it as is
  const clouds = bg || makeClouds();
  const out = new Float32Array(SIZE * SIZE * 3);
  for (let y = 0; y < SIZE; y++) {
    for (let x = 0; x < SIZE; x++) {
      const sx = flip ? SIZE - 1 - x : x;
      const si = (y * SIZE + sx) * 3, di = (y * SIZE + x) * 3;
      out[di] = clouds[si] / 255; out[di + 1] = clouds[si + 1] / 255; out[di + 2] = clouds[si + 2] / 255;
    }
  }
  await new Promise((r) => setImmediate(r)); // let the bot answer other messages

  const boltMask = newMask();
  if (!bg) { // the photo already has its own lightning bolt
    const bolt = makeBolt(rand, flip);
    const prof = (t) => Math.pow(Math.sin(Math.PI * clamp(t)), 0.6);
    strokeTapered(boltMask, bolt.main, (t) => 1.3 + 1.9 * prof(t), (t) => 0.4 + 0.6 * prof(t));
    for (const b of bolt.branches) strokePath(boltMask, b, 1.1, 0.45);
  }

  const { core, scribble, k } = drawText(lines, rand);
  const textAll = newMask();
  for (let i = 0; i < textAll.length; i++) textAll[i] = Math.max(core[i], scribble[i]);
  await new Promise((r) => setImmediate(r));

  const tA = boxBlur(textAll, k * 0.05), tB = boxBlur(textAll, k * 0.2), tC = boxBlur(textAll, k * 0.65);
  const bA = bg ? boltMask : boxBlur(boltMask, 4), bB = bg ? boltMask : boxBlur(boltMask, 12), bC = bg ? boltMask : boxBlur(boltMask, 34);
  const shade = boxBlur(textAll, Math.max(2, k * 0.05));   // soft dark shadow under the letters

  const buf = Buffer.alloc(SIZE * SIZE * 3);
  for (let y = 0; y < SIZE; y++) {
    for (let x = 0; x < SIZE; x++) {
      const i = y * SIZE + x;
      const si = clamp(y - 4, 0, SIZE - 1) * SIZE + clamp(x - 3, 0, SIZE - 1);
      const dark = 1 - 0.6 * clamp(shade[si] * 1.6);
      const g = clamp(tA[i] * 1.0 + tB[i] * 0.8 + tC[i] * 0.2 + bA[i] * 1.3 + bB[i] * 1.4 + bC[i] * 0.6);
      const a = clamp(Math.max(core[i], scribble[i], boltMask[i]));
      const grain = (rand() - 0.5) * 0.03;
      for (let c = 0; c < 3; c++) {
        const j = i * 3 + c;
        let v = out[j] * dark;
        v = 1 - (1 - v) * (1 - g * (GLOW[c] / 255));       // screen blend = light adds up
        v = lerp(v, CORE[c] / 255, a);                      // white cores on top
        buf[j] = clamp(v + grain) * 255;
      }
    }
  }
  return buf; // raw RGB, SIZE x SIZE
}

// ---------- save as picture ----------
const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; }
  return t;
})();
const crc32 = (buf) => { let c = 0xffffffff; for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 255] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; };
function pngChunk(type, data) {
  const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
  const td = Buffer.concat([Buffer.from(type), data]);
  const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(td));
  return Buffer.concat([len, td, crc]);
}
function encodePng(rgb) {
  const raw = Buffer.alloc((SIZE * 3 + 1) * SIZE);
  for (let y = 0; y < SIZE; y++) { raw[y * (SIZE * 3 + 1)] = 0; rgb.copy(raw, y * (SIZE * 3 + 1) + 1, y * SIZE * 3, (y + 1) * SIZE * 3); }
  const ihdr = Buffer.alloc(13); ihdr.writeUInt32BE(SIZE, 0); ihdr.writeUInt32BE(SIZE, 4); ihdr[8] = 8; ihdr[9] = 2;
  return Buffer.concat([Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]), pngChunk('IHDR', ihdr), pngChunk('IDAT', zlib.deflateSync(raw, { level: 6 })), pngChunk('IEND', Buffer.alloc(0))]);
}
async function encode(rgb) {
  try { // smaller file when sharp is installed
    const sharp = require('sharp');
    return await sharp(rgb, { raw: { width: SIZE, height: SIZE, channels: 3 } }).jpeg({ quality: 90 }).toBuffer();
  } catch {
    return encodePng(rgb);
  }
}

module.exports = [
  {
    command: ['thunder'],
    alias: ['storm', 'lightning'],
    description: 'Glowing thunder-storm text picture',
    category: 'Ephoto',
    use: '<your text>',
    filename: __filename,

    async execute(m, { ednut, q, text, reply, prefix }) {
      try {
        let raw = typeof text === 'string' && text.trim() ? text : Array.isArray(q) ? q.join(' ') : String(q || '');
        // no text typed: use the message you replied to
        if (!raw.trim() && m.quoted && m.quoted !== m) raw = m.quoted.text || m.quoted.body || '';
        if (!layoutLines(raw).length) {
          return await reply(`Give me a text.\nExample: ${prefix || '.'}thunder Devs`);
        }

        const rgb = await render(raw, (Date.now() ^ (Math.random() * 1e9)) >>> 0);
        const image = await encode(rgb);

        await ednut.sendMessage(
          m.chat,
          { image, caption: 'â¡ *Thunder text by EmmyFrosh-Ai*' },
          { quoted: m }
        );
      } catch (e) {
        console.error('[thunder]', e);
        await reply('â Could not make the picture. Please try again.');
      }
    },
  },
];

